const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
let idx = 0;
const n = input[idx++], m = input[idx++];

const a = new Array(n);
for (let i = 0; i < n; i++) a[i] = input[idx++];

const b = new Array(n);
for (let i = 0; i < n; i++) b[i] = input[idx++];

const totalLen = n * m;
const maxBalance = totalLen; // upper bound, but we will cap by totalLen/2 logically

// dp[balance] = minimal cost at current position with given balance
// initialize with Infinity
const INF = Number.POSITIVE_INFINITY;
let dp = new Float64Array(totalLen + 1);
for (let i = 0; i <= totalLen; i++) dp[i] = INF;
dp[0] = 0;

for (let i = 0; i < totalLen; i++) {
    const posMod = i % n;
    const next = new Float64Array(totalLen + 1);
    for (let k = 0; k <= totalLen; k++) next[k] = INF;

    const maxPossibleBalance = Math.min(i + 1, totalLen / 2);
    for (let bal = 0; bal <= maxPossibleBalance; bal++) {
        const cur = dp[bal];
        if (cur === INF) continue;

        // place '('
        if (bal + 1 <= totalLen / 2) {
            const costOpen = cur + (a[posMod] % n);
            if (costOpen < next[bal + 1]) next[bal + 1] = costOpen;
        }

        // place ')'
        if (bal > 0) {
            const costClose = cur + (b[posMod] % n);
            if (costClose < next[bal - 1]) next[bal - 1] = costClose;
        }
    }
    dp = next;
}

