const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
let idx = 0;

const n = input[idx++];
const m = input[idx++];

const a = new Array(n);
for (let i = 0; i < n; i++) a[i] = input[idx++];

const b = new Array(n);
for (let i = 0; i < n; i++) b[i] = input[idx++];

const totalLen = n * m;
const maxBalance = n; // balance can't exceed n because index mod n

// dp[pos_mod][balance] = minimal cost to reach this state
// we only need current and next layers over pos_mod
const INF = Number.MAX_SAFE_INTEGER;

// initialize dp for position 0
let dp = Array.from({ length: n }, () => new Array(maxBalance + 1).fill(INF));
dp[0][0] = 0;

// process positions 0 .. totalLen-1
for (let pos = 0; pos < totalLen; pos++) {
    const curMod = pos % n;
    const nextMod = (pos + 1) % n;

    const cur = dp[curMod];
    const next = dp[nextMod];

    // reset next layer
    for (let bIdx = 0; bIdx <= maxBalance; bIdx++) next[bIdx] = INF;

    for (let bal = 0; bal <= maxBalance; bal++) {
        const curCost = cur[bal];
        if (curCost === INF) continue;

        // open bracket
        if (bal + 1 <= maxBalance) {
            const costOpen = curCost + a[curMod];
            if (costOpen < next[bal + 1]) next[bal + 1] = costOpen;
        }

        // close bracket (only if balance > 0)
        if (bal > 0) {
            const costClose = curCost + b[curMod];
            if (costClose < next[bal - 1]) next[bal - 1] = costClose;
        }
    }
}

// final state: position totalLen, balance must be 0
const result = dp[totalLen % n][0];
